#!/usr/bin/env node
// Generated by Keel — byte budgets + split-doc integrity. Copy to .keel/doc-size.mjs.
// Usage: node .keel/doc-size.mjs [--json]      Self-test: node .keel/doc-size.mjs --self-test
// Read-only. Every file is measured once (no double-counting):
//   - AGENTS.md, CLAUDE.md, every top-level docs/*.md, and every key in .keel/meta.json "budgets";
//   - a SPLIT doc is a parent NAME.md with a sibling folder name/ (DESIGN.md → design/,
//     IMPLEMENTATION_PLAN.md → implementation-plan/). The parent (now an index) and each part are
//     measured separately against the parent's budget; the family total is reported, not judged.
// Budget = meta.budgets[path] ?? meta.defaultBudget ?? 32768 bytes.
// Breach action: "archive" (keystone: never split), "archive-then-split" (docs with archivable
// closed detail), else "split". A breach is work for doc-sync, not a failure.
// FAILS (exit 1) on link errors: a part not linked from its parent, or a part with no link back.
import { readdirSync, readFileSync, statSync, existsSync, writeFileSync, mkdirSync, mkdtempSync } from 'fs'
import { join, dirname, basename, relative } from 'path'
import { tmpdir } from 'os'

const KEYSTONE = new Set(['AGENTS.md', 'CLAUDE.md'])
const ARCHIVABLE = new Set(['docs/IMPLEMENTATION_PLAN.md', 'CHANGELOG.md', 'docs/CHANGELOG.md',
  'docs/RUNBOOK.md', 'docs/DEPLOYMENT.md', 'docs/adr/README.md'])
const kebab = f => basename(f, '.md').toLowerCase().replace(/_/g, '-')
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

export function check(root) {
  let meta = {}
  try { meta = JSON.parse(readFileSync(join(root, '.keel/meta.json'), 'utf8')) } catch {}
  const budgets = meta.budgets || {}
  const def = meta.defaultBudget || 32768
  const mds = d => existsSync(join(root, d)) ? readdirSync(join(root, d)).filter(f => f.endsWith('.md')).map(f => d ? `${d}/${f}` : f) : []
  const docs = new Set([...['AGENTS.md', 'CLAUDE.md'].filter(f => existsSync(join(root, f))), ...mds('docs'),
    ...Object.keys(budgets).filter(f => existsSync(join(root, f)))])
  const files = [], breaches = [], linkErrors = [], families = []
  const size = f => statSync(join(root, f)).size
  for (const doc of docs) {
    const budget = budgets[doc] ?? def
    const measure = (f, part) => {
      const s = size(f); files.push({ file: f, size: s, budget, part: part || null })
      if (s > budget) breaches.push({ file: f, size: s, budget,
        action: KEYSTONE.has(f) ? 'archive' : ARCHIVABLE.has(f) ? 'archive-then-split' : 'split' })
      return s
    }
    let total = measure(doc)
    const folder = join(dirname(doc), kebab(doc))
    if (KEYSTONE.has(doc) || basename(doc) === 'README.md' || !existsSync(join(root, folder)) ||
        !statSync(join(root, folder)).isDirectory()) continue
    const parentText = readFileSync(join(root, doc), 'utf8')
    const parts = readdirSync(join(root, folder)).filter(f => f.endsWith('.md')).sort()
    for (const p of parts) {
      const rel = `${folder}/${p}`
      total += measure(rel, doc)
      if (!new RegExp(`\\]\\((\\./)?${esc(kebab(doc))}/${esc(p)}(#[^)]*)?\\)`).test(parentText))
        linkErrors.push(`${rel}: not linked from ${doc}`)
      if (!new RegExp(`\\]\\(\\.\\./${esc(basename(doc))}(#[^)]*)?\\)`).test(readFileSync(join(root, rel), 'utf8')))
        linkErrors.push(`${rel}: no link back to ../${basename(doc)}`)
    }
    families.push({ parent: doc, folder, parts: parts.length, total })
  }
  return { ok: linkErrors.length === 0, breaches, linkErrors, families, files }
}

if (process.argv.includes('--self-test')) {
  const r = mkdtempSync(join(tmpdir(), 'keel-size-'))
  const w = (f, s) => { mkdirSync(dirname(join(r, f)), { recursive: true }); writeFileSync(join(r, f), s) }
  w('.keel/meta.json', JSON.stringify({ budgets: { 'AGENTS.md': 50 }, defaultBudget: 100 }))
  w('AGENTS.md', 'x'.repeat(60))                                   // keystone breach → archive
  w('docs/PRD.md', 'y'.repeat(120))                                // → split
  w('docs/DESIGN.md', '# D\n[a](design/01-a.md) [b](./design/02-b.md)\n')
  w('docs/design/01-a.md', '> Part of [DESIGN.md](../DESIGN.md)\n' + 'z'.repeat(40))
  w('docs/design/02-b.md', 'no back link')                        // back-link error
  w('docs/design/03-c.md', '[up](../DESIGN.md#parts)')             // not linked from parent
  w('docs/IMPLEMENTATION_PLAN.md', 'p'.repeat(101))                // → archive-then-split
  const c = check(r)
  const act = Object.fromEntries(c.breaches.map(b => [b.file, b.action]))
  const ok = !c.ok && act['AGENTS.md'] === 'archive' && act['docs/PRD.md'] === 'split' &&
    act['docs/IMPLEMENTATION_PLAN.md'] === 'archive-then-split' && !act['docs/design/01-a.md'] &&
    c.linkErrors.length === 2 && c.linkErrors.some(e => e.startsWith('docs/design/02-b.md: no link back')) &&
    c.linkErrors.some(e => e.startsWith('docs/design/03-c.md: not linked')) &&
    c.families[0].parts === 3 && c.files.filter(f => f.file === 'docs/DESIGN.md').length === 1
  console.log(ok ? 'ok' : 'FAIL ' + JSON.stringify(c, null, 1)); process.exit(ok ? 0 : 1)
}

const res = check('.')
if (process.argv.includes('--json')) console.log(JSON.stringify(res, null, 1))
else {
  for (const f of res.files) console.log(`${f.size > f.budget ? '⚠️ ' : '✅'} ${f.file} ${f.size}/${f.budget}B${f.part ? ` (part of ${f.part})` : ''}`)
  for (const fam of res.families) console.log(`   ${fam.parent} + ${fam.parts} parts in ${fam.folder}/ = ${fam.total}B total`)
  for (const b of res.breaches) console.log(`BREACH ${b.file} ${b.size}B > ${b.budget}B → ${b.action}`)
  for (const e of res.linkErrors) console.log(`LINK ERROR ${e}`)
}
process.exit(res.ok ? 0 : 1)
